-- =====================================================================
-- DelhiDrive — refresh fleet + coupons to the live NCR Drive catalogue
-- =====================================================================
-- Run this in Supabase: SQL Editor -> New query -> paste -> Run.
--
-- Replaces the 14 placeholder demo cars with the real 23-vehicle fleet
-- (actual names, photos and 6h/12h/24h prices). Existing bookings are
-- untouched. Safe to run more than once.
-- =====================================================================

-- Remove the old placeholder cars (their ids all began with these stems).
delete from public.fleet
where id like 'dd-swift-%'  or id like 'dd-i20-%'    or id like 'dd-tiago-%'
   or id like 'dd-city-%'   or id like 'dd-verna-%'  or id like 'dd-slavia-%'
   or id like 'dd-creta-0%' or id like 'dd-nexon-%'  or id like 'dd-scorpio-0%'
   or id like 'dd-xuv700-%' or id like 'dd-thar-1%'  or id like 'dd-c200-%'
   or id like 'dd-bmw3-%'   or id like 'dd-fortuner-%';

-- Upsert the real fleet. Re-running refreshes prices without duplicating.
on conflict (id) do update set data = excluded.data;

-- Promo codes (WELCOME10 replaces FIRST500 to match the old site).
delete from public.coupons where id = 'cp-first500';
on conflict (id) do update set data = excluded.data;

